#!/usr/bin/env bash
#
# PocketPills — fix prescription medicine extraction on handwritten South Asian Rx.
#
#  1. Adds src/lib/rxLexicon.ts — letterhead/vitals/advice rejection, South Asian
#     sig parsing (OD/BD/TDS/HS/AC/PC, 1-0-1 grids, clock times), bare-number
#     strengths, and a brand-spelling lexicon.
#  2. rxOcr.ts — medicine lines must now carry a real Rx signal. "Looks
#     capitalised" is no longer a signal (that is what produced
#     "SENIOR MEDICAL OFFICER" and "Cellow for IMO").
#  3. rxOcr.ts — the handwriting pass now triggers on a missing MEDICINE signal
#     rather than missing text, so a printed letterhead no longer suppresses it.
#  4. lineSegments.ts — splits line bands into columns, so vitals on the left
#     stop being glued to the Rx list on the right.
#
# Safe to re-run. Backs up touched files; verifies with tsc + vite build.
#
set -euo pipefail

grep -q '"pocketpills-redesign"' package.json 2>/dev/null || {
  echo "!! Run from the pocketpills repo root."; exit 1; }
[ -f src/lib/localHtr/htrClient.ts ] || {
  echo "!! Run apply-htr-handwriting.sh first (src/lib/localHtr missing)."; exit 1; }

BK=".rxfix-backup-$(date +%Y%m%d-%H%M%S)"
mkdir -p "${BK}/src/lib/localHtr"
echo ">> Backups -> ${BK}/"
cp src/lib/rxOcr.ts "${BK}/src/lib/rxOcr.ts"
cp src/lib/localHtr/lineSegments.ts "${BK}/src/lib/localHtr/lineSegments.ts"

echo ">> Writing src/lib/rxLexicon.ts"
printf '%s' "" | base64 -d > src/lib/rxLexicon.ts

echo ">> Patching rxOcr.ts + lineSegments.ts"
if grep -q "rxLexicon" src/lib/rxOcr.ts; then
  echo "   already patched — skipping"
else
  PATCH=""
  if printf '%s' "$PATCH" | base64 -d | git apply -p1 --check - 2>/dev/null; then
    printf '%s' "$PATCH" | base64 -d | git apply -p1 -
    echo "   applied via git apply"
  elif printf '%s' "$PATCH" | base64 -d | patch -p1 --dry-run >/dev/null 2>&1; then
    printf '%s' "$PATCH" | base64 -d | patch -p1
    echo "   applied via patch"
  else
    echo "!! Patch did not apply cleanly. Backup at ${BK}."; exit 2
  fi
fi

echo ">> Verifying (tsc)"; npx tsc -b --noEmit
echo ">> Verifying (vite build)"; npx vite build >/dev/null
echo ""
echo "Done. Backup: ${BK}"
echo "Rollback: cp -r ${BK}/src ./ && rm -f src/lib/rxLexicon.ts"
